{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.PURCHASE_ORDER_JOURNEY as with eanmapp as ( select ean, sku from snitch_db.maplemonk.ean_to_sku_mapping ), podata as ( select IFNULL(e.sku,logic_user_code) as sku, UPPER(TRIM(REGEXP_REPLACE(sku::STRING, \'-[^-]+$\', \'\'))) AS sku_group, UPPER(TRIM(logic_user_code)) as logicusercode, lot_number, pending_qty, total_qty, origin, order_date, EDD, from_party, to_party, vouch_code, order_prefix, action_code, order_number, supplier_order_no, transfer_branch_code, po_mrp from SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER p left join eanmapp e on UPPER(TRIM(p.logic_user_code::VARCHAR)) = UPPER(TRIM(e.ean::VARCHAR)) where origin is not null and order_date >= \'2025-01-01\' and origin = \'VENDOR-WH\' and transfer_branch_code in (8,94) ) , pv as ( select origin, lot_number, bill_date, vouch_date as PO_DATE, branch_code, item_quantity, to_party, from_party, sku, bill_no, doc_type, vouch_no, item_mrp, lot_code, item_pur_rate, agent_name, concat(grn_prefix,\'-\',grn_number) as helper1 from snitch_db.maplemonk.logic_purchase_voucher where origin = \'VENDOR-WH\' ) , uc_po as ( select created, updated, UPPER(category) as CATEGORY, facility, \"PO Code\" as UC_PO_CODE, TRIM(UPPER(\"Item SkuCode\")) as UC_SKU, \"Delivery Date\" as UC_DELIVERY_DATE, \"PO Created By\" as UC_CREATED_BY, \"Vendor Name\" as VENDOR_NAME, \"Item Type Name\", \"Order Quantity\"::INTEGER as PO_QTY, \"PO Approved Date\", \"Pending Quantity\"::INTEGER as UC_PENDING_QTY, UPPER(\"Rejection Reason\") as REASON_REJECT, \"Recieved Quantity\"::INTEGER AS RECEIVED_QTY, \"Rejected Quantity\"::INTEGER as REJECT_QTY, \"Purchase Order Status\" as PO_STATUS from snitch_db.maplemonk.uc_final_get_purchase_orders where lower(\"Vendor Name\") not in (\'photoshoot\',\'wrong products\',\'shiprocket\',\'sarath city hyderabad\',\'landmark gandhinagar\',\'lulu mall\', \'highstreet-rajpurroad\',\'neptune trion\',\'bhartiya city\') and \"Vendor Name\" not like \'%SNITCH%\' and \"Vendor Name\" not like \'%SAPL%\' and lower(\"Vendor Name\") not like \'%store%\' and \"PO Created By\" in (\'tech@snitch.com\',\'logic@snitch.co.in\') and created::DATE >= \'2024-10-01\' ), compile as ( select lp.sku, lp.sku_group, lp.logicusercode, lp.lot_number, total_qty, pending_qty, lp.origin, order_date, edd, bill_date, PO_Date, lp.from_party, lp.transfer_branch_code, lp.to_party, vouch_code, transfer_branch_code as branchcode, po_mrp as mrp, item_pur_rate as cp, bill_no, vouch_no, lot_code, order_prefix, action_code, order_number, pv.helper1, up.created as UC_CREATED, up.updated as UC_UPDATED, up.CATEGORY, up.facility, up.UC_PO_CODE, up.UC_SKU, up.UC_DELIVERY_DATE, up.UC_CREATED_BY, up.VENDOR_NAME, up.\"Item Type Name\" as PRODUCT_NAME, up.PO_QTY, up.\"PO Approved Date\" as approved_date, up. UC_PENDING_QTY, up. REASON_REJECT, up. RECEIVED_QTY, up. REJECT_QTY, up. PO_STATUS from podata lp left join pv on CONCAT(lp.lot_number,lp.sku) = concat(pv.lot_number,pv.sku) left join uc_po up on CONCAT(UPPER(TRIM(pv.helper1)),UPPER(TRIM(pv.sku))) = CONCAT(UPPER(TRIM(up.UC_PO_CODE)),UPPER(TRIM(up.UC_SKU))) ) select total_qty - received_qty AS DELTA , CASE WHEN PO_DATE IS NULL THEN \'PV_PENDING\' WHEN PO_STATUS IS NULL THEN \'UC_CREATION_PENDING\' ELSE \'COMPLETE\' END AS FINAL_PO_STATUS, CASE WHEN FINAL_PO_STATUS = \'PV_PENDING\' THEN TIMESTAMPDIFF(DAY,ORDER_DATE,CURRENT_DATE) WHEN FINAL_PO_STATUS = \'UC_CREATION_PENDING\' THEN TIMESTAMPDIFF(DAY,PO_DATE,CURRENT_DATE) ELSE NULL END AS AGEING, * from compile ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            